CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "StatusServidor" AS ENUM ('Ativo', 'Inativo', 'Aposentado');
CREATE TYPE "Role" AS ENUM ('ADMIN', 'OPERADOR', 'PASTA');
CREATE TYPE "CategoriaDocumento" AS ENUM ('Pasta_Fisica_Digitalizada', 'Posse_Eletronica', 'Documentos_Pessoais', 'Publicacoes', 'Certidoes_Declaracoes');
CREATE TYPE "StorageBackend" AS ENUM ('LOCAL', 'SUPABASE', 'S3');
CREATE TYPE "AcaoAuditoria" AS ENUM ('CONSULTA', 'ATUALIZACAO', 'EXCLUSAO', 'UPLOAD', 'IMPRESSAO', 'EXPORTACAO', 'ENCAMINHAMENTO', 'PESQUISA_OCR');
CREATE TABLE "servidores" ("id" TEXT PRIMARY KEY, "matricula" TEXT NOT NULL UNIQUE, "matriculaCargoEfetivo" TEXT NOT NULL DEFAULT '', "nome" TEXT NOT NULL, "cpf" TEXT NOT NULL UNIQUE, "fotoUrl" TEXT, "fotoStorageBackend" "StorageBackend", "fotoStorageKey" TEXT, "fotoMimeType" TEXT, "cargoEfetivo" TEXT NOT NULL, "cargoOcupado" TEXT NOT NULL, "lotacao" TEXT NOT NULL, "status" "StatusServidor" NOT NULL DEFAULT 'Ativo', "role" "Role" NOT NULL DEFAULT 'PASTA', "dataIngresso" TEXT NOT NULL, "email" TEXT NOT NULL, "telefone" TEXT NOT NULL, "senhaHash" TEXT, "senhaDefinidaEm" TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "password_reset_tokens" ("id" TEXT PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "servidorId" TEXT NOT NULL REFERENCES "servidores"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "documentos_pdf" ("id" TEXT PRIMARY KEY, "servidorId" TEXT NOT NULL REFERENCES "servidores"("id") ON DELETE CASCADE ON UPDATE CASCADE, "titulo" TEXT NOT NULL, "categoria" "CategoriaDocumento" NOT NULL, "dataUpload" TEXT NOT NULL, "tamanho" TEXT NOT NULL, "paginas" INTEGER NOT NULL DEFAULT 1, "processoSEI" TEXT, "arquivoUrl" TEXT NOT NULL, "storageBackend" "StorageBackend", "storageKey" TEXT, "textoOCR" TEXT NOT NULL, "operadorRH" TEXT NOT NULL, "ordem" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "storage_deletion_tasks" ("id" TEXT PRIMARY KEY, "backend" "StorageBackend" NOT NULL, "storageKey" TEXT NOT NULL UNIQUE, "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "processedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "encaminhamentos" ("id" TEXT PRIMARY KEY, "servidorId" TEXT NOT NULL REFERENCES "servidores"("id") ON DELETE CASCADE ON UPDATE CASCADE, "documentoId" TEXT REFERENCES "documentos_pdf"("id") ON DELETE SET NULL ON UPDATE CASCADE, "destinatario" TEXT NOT NULL, "justificativa" TEXT NOT NULL, "validadeDias" INTEGER NOT NULL, "requerSenha" BOOLEAN NOT NULL DEFAULT true, "token" TEXT NOT NULL UNIQUE, "dataGeracao" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "dataExpiracao" TIMESTAMP(3) NOT NULL);
CREATE TABLE "logs_auditoria" ("id" TEXT PRIMARY KEY, "dataHora" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "operador" TEXT NOT NULL, "operadorMatricula" TEXT NOT NULL, "acao" "AcaoAuditoria" NOT NULL, "detalhes" TEXT NOT NULL, "ip" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "password_reset_tokens_servidorId_expiresAt_idx" ON "password_reset_tokens"("servidorId", "expiresAt");
CREATE INDEX "documentos_pdf_servidorId_ordem_idx" ON "documentos_pdf"("servidorId", "ordem");
CREATE INDEX "documentos_pdf_createdAt_idx" ON "documentos_pdf"("createdAt");
CREATE INDEX "storage_deletion_tasks_processedAt_createdAt_idx" ON "storage_deletion_tasks"("processedAt", "createdAt");
CREATE INDEX "encaminhamentos_dataGeracao_idx" ON "encaminhamentos"("dataGeracao");
CREATE INDEX "encaminhamentos_dataExpiracao_idx" ON "encaminhamentos"("dataExpiracao");
CREATE INDEX "logs_auditoria_createdAt_idx" ON "logs_auditoria"("createdAt");
CREATE INDEX "logs_auditoria_acao_createdAt_idx" ON "logs_auditoria"("acao", "createdAt");
